/* Developer experience: documented endpoints, illustrative adoption architectures. */
const D_MODES=[
{label:'Do zero',title:'Seu próximo produto. Sua experiência.',copy:'Construa a interface e as regras que diferenciam o negócio. Componha identidade, decisão, documentos e comunicação por trás dela. O primeiro recorte pode ser uma jornada inteira ou apenas uma operação.',nodes:['Web / mobile','Seu backend','Identidade','Decisão','Documentos','Seu banco de dados'],detail:'Exemplo: uma proposta de crédito nasce na sua interface, passa pela política publicada e segue para formalização. Você define a experiência, os dados de domínio e os pontos de aprovação.',keep:'Interface, domínio e estratégia de produto',add:'Capacidades e integrações selecionadas'},
{label:'Com o que já existe',title:'O sistema continua. Uma parte evolui.',copy:'Escolha uma fronteira clara no sistema atual: calcular uma condição, avaliar uma política ou emitir um documento. Seu backend adapta o contrato existente à capacidade escolhida e mantém a jornada sob seu controle.',nodes:['ERP / CRM','Seu adaptador','Cálculo','Decisão','Assinatura','Core existente'],detail:'Exemplo: o CRM continua abrindo propostas e o core continua registrando contratos. Uma chamada ao Decision Engine substitui a política espalhada em serviços. Amplie o recorte depois de validar o primeiro.',keep:'Core, cadastros e contratos existentes',add:'Uma capacidade atrás do seu adaptador'},
{label:'Cirúrgico no mobile',title:'Uma nova capacidade. No app que já está lá.',copy:'Insira uma função no ponto certo da jornada: simulação, consulta de elegibilidade ou uma etapa de verificação. O aplicativo conversa com seu backend, que controla credenciais, autorização e a integração com a Catalisa.',nodes:['Seu aplicativo','Seu BFF / backend','Simulação','Decisão','Verificação','Jornada atual'],detail:'Exemplo: uma nova tela de simulação em um aplicativo existente. O BFF chama o serviço escolhido e devolve um modelo pronto para a tela. A integração é via API; não pressupõe um SDK mobile ou uma interface pronta.',keep:'App, navegação e sessão do usuário',add:'Uma operação exposta pelo seu backend'}];
const D_CALLS=[{name:'Decisão',method:'POST',path:'/decision-engine/api/v1/decisions/{decisionId}/execute',body:{input:{age:25}},slug:'decision-engine',note:'Exemplo de entrada para uma decisão de idade. Requer decisão ACTIVE e uma versão publicada; os campos de input pertencem à sua tabela DMN.'},{name:'IA aplicada',method:'POST',path:'/ai-engine/api/v1/ai/classify',body:{text:'Quero renegociar meu contrato.',categories:['renegociacao','duvida','reclamacao']},slug:'ai-engine',note:'Classificação de texto com categorias definidas pela sua operação. Configure os provedores disponíveis no ambiente.'},{name:'Eventos',method:'GET',path:'/webhooks-engine/api/v1/delivery-logs',body:null,slug:'webhooks-engine',note:'Consulta ao histórico de entregas do escopo autorizado. A paginação, os filtros e o formato de resposta estão na referência do bloco.'}];
function dCode(i=0,lang='curl'){const a=D_CALLS[i];if(lang==='JavaScript')return `// Execute no backend. Configure ambiente e credencial.\nconst base = process.env.CATALISA_BASE_URL;\nconst token = process.env.CATALISA_TOKEN;\nconst path = '${a.path}';\n\nconst response = await fetch(base + path, {\n  method: '${a.method}',\n  headers: {\n    Authorization: \`Bearer \${token}\`,\n    'Content-Type': 'application/json'\n  }${a.body?',\n  body: JSON.stringify('+JSON.stringify(a.body,null,2).replaceAll('\n','\n  ')+')':''}\n});\n\nif (!response.ok) {\n  throw new Error(\`HTTP \${response.status}\`);\n}\nconst result = await response.json();`;return `# Configure a URL e o token do seu ambiente.\n# Substitua {decisionId}, quando aplicável.\ncurl --fail-with-body --request ${a.method} \\\n  "$CATALISA_BASE_URL${a.path}" \\\n  --header "Authorization: Bearer $CATALISA_TOKEN"${a.body?' \\\n  --header "Content-Type: application/json" \\\n  --data \''+JSON.stringify(a.body,null,2)+'\'':''}`;}
function dNodeLabel(text,x,y,w,h){const max=Math.floor((w-24)/8);const lines=[];for(const word of text.split(' ')){if(!lines.length||lines[lines.length-1].length+word.length+1>max)lines.push(word);else lines[lines.length-1]+=' '+word;}return lines.map((line,k)=>`<tspan x="${x+w/2}" y="${y+h/2+5+(k-(lines.length-1)/2)*18}">${ce(line)}</tspan>`).join('');}
function dMap(i=0){const m=D_MODES[i];return `<svg viewBox="0 0 680 380" role="img" aria-label="${ce(m.label)}: interface conecta ao seu backend, que integra capacidades e sistemas existentes"><defs><pattern id="d-grid" width="24" height="24" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="#54455e"/></pattern></defs><rect width="680" height="380" fill="url(#d-grid)"/><g fill="none" stroke="#c6a9e6" stroke-width="2"><path d="M150 190H240M420 190H510M420 190h35V80h55M455 190v110h55M330 230v85H150"/><path class="d-flow" stroke="#ff9a51" stroke-width="3" stroke-dasharray="7 15" d="M150 190H240M420 190H510M420 190h35V80h55M455 190v110h55"/></g>${[[20,150,130,80],[240,145,180,90],[510,50,150,60],[510,160,150,60],[510,270,150,60],[20,285,130,60]].map(([x,y,w,h],j)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${j===0?22:4}" fill="${j===1?'#f08d49':j>1&&j<5?'#724e96':'#292331'}" stroke="${j===1?'#fbb87f':'#826d94'}"/><text x="${x+w/2}" y="${y+h/2+5}" fill="${j===1?'#201728':'#fff'}" text-anchor="middle" font-family="monospace" font-size="13">${dNodeLabel(m.nodes[j],x,y,w,h)}</text>`).join('')}</svg>`;}
function dMode(i=0){let m=D_MODES[i];return `<div class="d-mode-copy"><span class="d-kicker">PADRÃO DE ADOÇÃO / 0${i+1}</span><h3>${m.title}</h3><p>${m.copy}</p><dl><dt>Você mantém</dt><dd>${m.keep}</dd><dt>Você conecta</dt><dd>${m.add}</dd></dl></div><div class="d-map">${dMap(i)}<p>${m.detail}</p><small>Arquitetura de referência ilustrativa. O recorte depende do contrato de cada capacidade.</small></div>`;}
function dApi(i=0,lang='curl'){const a=D_CALLS[i];return `<div class="d-endpoint"><b>${a.method}</b><code>${ce(a.path)}</code></div><div class="d-editor-top"><div>${['curl','JavaScript'].map(l=>`<button data-d-lang="${l}" aria-pressed="${l===lang}">${l}</button>`).join('')}</div><button data-d-copy>Copiar código ↗</button></div><pre tabindex="0"><code id="d-code">${ce(dCode(i,lang))}</code></pre><p class="d-code-note">${a.note}</p><a class="d-link" href="https://docs.catalisa.app/blocks/${a.slug}/">Contrato completo e pré-requisitos ↗</a>`;}
function cDevelopers(){return `<div class="d-page"><section class="d-hero"><div class="wrap d-hero-grid"><div><span class="d-kicker">CATALISA / DEVELOPERS</span><h1>Seu código.<br>Mais <em>possibilidades.</em></h1><p>De uma chamada de API a um produto inteiro. Conecte capacidades ao que você já construiu — ou use essa base para começar algo novo.</p><div class="d-actions"><a class="d-button" href="https://docs.catalisa.app/">Abrir documentação ↗</a><a href="#d-api">Explorar a API ↓</a></div><div class="d-tags"><span>API-first</span><span>Composição modular</span><span>Integração progressiva</span></div></div><div class="d-hero-art"><div class="d-window-bar"><span>● ● ●</span><span>product.compose</span><span>↗</span></div><div class="d-compose"><span class="d-comment">// o que torna seu produto único</span><strong>your.product<span>()</span></strong><div class="d-plugs"><span>interface</span><span>domínio</span><span>experiência</span></div><div class="d-cable"></div><div class="d-core"><span>catalisa</span><b>connect()</b></div><div class="d-module-grid"><div>01 <b>identity</b></div><div>02 <b>decision</b></div><div>03 <b>payments</b></div><div>04 <b>documents</b></div><div>05 <b>ai</b></div><div>06 <b>events</b></div></div><span class="d-art-note">Uma representação de composição, não sintaxe de SDK.</span></div></div></div></section><nav class="d-subnav" aria-label="Nesta página"><div class="wrap"><a href="#d-adopt">01 / Integre</a><a href="#d-api">02 / Chame</a><a href="#d-recipes">03 / Componha</a><a href="#d-operate">04 / Opere</a></div></nav>
<section class="wrap d-section" id="d-adopt"><div class="d-heading"><span class="d-kicker">COMECE NO SEU CONTEXTO</span><h2>A melhor integração<br>cabe no seu sistema.</h2><p>Você escolhe a fronteira. Um building block para resolver uma responsabilidade, uma composição para sustentar uma jornada ou a plataforma como base de um novo produto.</p></div><div class="d-tabs" aria-label="Padrões de adoção">${D_MODES.map((m,i)=>`<button data-d-mode="${i}" aria-pressed="${i===0}">${m.label}<span>0${i+1}</span></button>`).join('')}</div><div class="d-adoption" id="d-mode-panel" aria-live="polite">${dMode()}</div></section>
<section class="d-api-section" id="d-api"><div class="wrap d-api-grid"><div><span class="d-kicker">HTTP. JSON. SEU STACK.</span><h2>Menos adivinhação.<br><em>Mais contrato.</em></h2><p>Consuma a API com as ferramentas que seu time já usa. Cada capacidade tem operações, entradas, permissões e limites próprios.</p><div class="d-api-options">${D_CALLS.map((a,i)=>`<button data-d-api="${i}" aria-pressed="${i===0}"><span>0${i+1}</span>${a.name}<b>↗</b></button>`).join('')}</div><p class="d-small">Exemplos de integração baseados na documentação. Configure credenciais e recursos no seu ambiente antes de executar. Esta página não envia requisições.</p></div><div class="d-code-window" id="d-api-panel">${dApi()}</div></div></section>
<section class="wrap d-section"><div class="d-heading"><span class="d-kicker">FLEXIBILIDADE COM FRONTEIRAS CLARAS</span><h2>Plugável onde importa.<br>Seu produto no comando.</h2></div><div class="d-principles"><article><span class="d-glyph">{ }</span><h3>A interface é sua.</h3><p>Web, app nativo, portal interno ou canal conversacional. Organize a experiência no seu frontend e exponha pelo backend somente o que aquela jornada precisa.</p></article><article><span class="d-glyph">⇄</span><h3>O provedor pode mudar.</h3><p>Blocos com drivers desacoplam a operação do fornecedor. No AI Engine, a escolha de provedor é configurável; no Payments e BaaS, confira os adaptadores e operações suportados antes de integrar.</p><a href="https://docs.catalisa.app/blocks/ai-engine/">Explore provedores ↗</a></article><article><span class="d-glyph">[+]</span><h3>O recorte pode crescer.</h3><p>Comece pela decisão. Acrescente documentos quando fizer sentido. Conecte comunicação depois. Valide as dependências de cada bloco e evolua por etapas que seu time consegue operar.</p></article></div></section>
<section class="d-recipes-section" id="d-recipes"><div class="wrap"><div class="d-heading"><span class="d-kicker">RECEITAS DE ARQUITETURA</span><h2>O que você quer<br>colocar de pé?</h2><p>Possibilidades de composição para sair da página em branco. Os fluxos abaixo são propostas de integração, não pacotes prontos.</p></div><div class="d-recipes">${[
['01','Crédito dentro do seu produto','Sua tela recebe a proposta. Seu backend prepara os dados, chama a decisão e encaminha a formalização quando a política permitir.','decision-engine,pricing-engine,e-signature','Mantenha limites, alçadas e exceções explícitos.','credit'],
['02','Banking com identidade própria','Uma experiência de conta com seu desenho e sua navegação. Componha a porta de entrada do aplicativo com as operações financeiras oferecidas pelos provedores habilitados.','banking,baas,open-finance','Defina quem registra cada operação e como conciliar o resultado.','bank'],
['03','IA no atendimento que já existe','Seu CRM recebe a mensagem. Uma chamada classifica a intenção; a aplicação usa esse resultado para sugerir uma fila ou uma próxima ação, com revisão nos casos definidos pelo negócio.','ai-engine,wpp-business,webhooks-engine','Separe sugestão de execução e mantenha o contexto autorizado.','ai'],
['04','Uma função nova no seu app','Adicione uma simulação ou uma etapa de verificação sem redesenhar a navegação inteira. Seu BFF traduz a resposta da API para a experiência mobile.','calculations-engine,biometrics,feature-flags','Avalie privacidade, permissões e estágio de cada bloco.','mobile']
].map(([n,t,p,slugs,note,art])=>`<article class="d-recipe ${art}"><div class="d-recipe-art" aria-hidden="true"><span>${n}</span><div class="d-symbol">${art==='credit'?'↗':art==='bank'?'▥':art==='ai'?'✳':'▯'}</div><code>${art}.compose</code></div><div class="d-recipe-body"><h3>${t}</h3><p>${p}</p><div class="d-chips">${slugs.split(',').map(s=>`<a href="https://docs.catalisa.app/blocks/${s}/">${s} ↗</a>`).join('')}</div><small>${note}</small></div></article>`).join('')}</div></div></section>
<section class="wrap d-section" id="d-operate"><div class="d-heading"><span class="d-kicker">DO PRIMEIRO REQUEST À OPERAÇÃO</span><h2>O código integra.<br>O contrato sustenta.</h2></div><div class="d-operate-grid"><div class="d-event-board"><span class="d-kicker">EVENT DELIVERY / VISÃO CONCEITUAL</span><h3>O evento tem<br>um caminho de volta.</h3><ol><li><b>01</b><div>Uma ação acontece<small>no bloco de origem</small></div></li><li><b>02</b><div>Uma assinatura seleciona eventos<small>no Webhooks Engine</small></div></li><li><b>03</b><div>Seu endpoint recebe<small>valida a assinatura e processa com idempotência</small></div></li><li><b>04</b><div>A entrega deixa histórico<small>consulte tentativas e investigue falhas</small></div></li></ol><a href="https://docs.catalisa.app/blocks/webhooks-engine/">Explore o contrato de eventos ↗</a></div><div class="d-checks">${[['Credenciais com intenção','Use IAM e o mecanismo de autenticação adequado ao contrato. API Keys permite delimitar acesso por rota e administrar rotação e revogação. Credenciais de serviço ficam no backend.','api-keys'],['Contexto de organização','Resolva a organização a partir da identidade autorizada. A aplicação deve preservar essa fronteira ao chamar os blocos e ao persistir seus próprios dados.','iam'],['Versões que explicam decisões','No Decision Engine, a política tem versão e a execução deixa registro. Planeje casos de regressão antes de publicar uma nova política.','decision-engine'],['Falhas previstas no desenho','Defina timeout, tratamento de erros e estratégia de recuperação. Em eventos, valide a assinatura e evite repetir efeitos de negócio quando uma entrega for reenviada.','webhooks-engine']].map(([t,p,s])=>`<article><h3>${t}</h3><p>${p}</p><a href="https://docs.catalisa.app/blocks/${s}/">Referência ↗</a></article>`).join('')}</div></div></section>
<section class="d-start"><div class="wrap"><span class="d-kicker">SEU PRIMEIRO RECORTE</span><h2>Escolha uma responsabilidade.<br><em>Construa a partir dela.</em></h2><div class="d-start-steps"><div><b>01</b><h3>Encontre a peça</h3><p>Escolha o domínio e confira o estágio da capacidade.</p></div><div><b>02</b><h3>Leia o contrato</h3><p>Valide autenticação, dependências, entradas e respostas.</p></div><div><b>03</b><h3>Integre uma jornada</h3><p>Teste o caminho feliz, as falhas e os efeitos no seu sistema.</p></div></div><div class="d-actions"><a class="d-button" href="https://docs.catalisa.app/">Ir para a documentação ↗</a><a href="/capacidades/">Explorar building blocks ↗</a><a href="/lab/">Imaginar uma composição ↗</a></div><p class="d-small">Produção, Beta e Alpha indicam estágios diferentes. Disponibilidade, dependências e escopo devem ser confirmados na documentação de cada bloco.</p></div></section></div>`;}
const dPreviousPage=cPage;cPage=function(route,blocks){return route==='/desenvolvedores/'?cDevelopers():dPreviousPage(route,blocks)};
if(typeof document!=='undefined')document.addEventListener('DOMContentLoaded',()=>{const root=document.querySelector('.d-page');if(!root)return;let api=0,lang='curl';root.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.dMode!==undefined){root.querySelectorAll('[data-d-mode]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.getElementById('d-mode-panel').innerHTML=dMode(Number(b.dataset.dMode));}if(b.dataset.dApi!==undefined){api=Number(b.dataset.dApi);root.querySelectorAll('[data-d-api]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.getElementById('d-api-panel').innerHTML=dApi(api,lang);}if(b.dataset.dLang){lang=b.dataset.dLang;document.getElementById('d-api-panel').innerHTML=dApi(api,lang);document.querySelector(`[data-d-lang="${lang}"]`).focus();}if(b.hasAttribute('data-d-copy')){try{await navigator.clipboard.writeText(dCode(api,lang));b.textContent='Código copiado ✓';}catch{b.textContent='Selecione e copie o código abaixo';}}});});
